// Couple cut-outs and painted motif sprites (spec 2.3.4, 1.7, 5.2, 6.6): manifest access, hashed URLs and `sizes`
// derived from the height-based layout (the couple is sized by height; the browser picks by width, so the layout
// table in breakpoints.ts is converted to widths here). src/assets/sprites.json is generated by tools/plates.
import manifest from '../assets/sprites.json';
import type { EventKey } from '../i18n/types';
import { COUPLE_HEIGHT, COUPLE_MAX_PX, type HeightClamp } from './breakpoints';
import type { PictureSource } from './plates';

export interface CoupleEntry {
  source: string;
  /** width / height of the sprite files */
  aspect: number;
  /** crown, feet, centre as fractions of the sprite height / width */
  figure: { cx: number; crown: number; feet: number };
  /** drawn this much smaller than the others (Mehndi's raised hands, the Reception's floor ring) */
  heightScale: number;
  palette: string;
  avif: Record<string, string>;
  webp: Record<string, string>;
  /** real pixel width per height key (Haldi's "960" file is 927 px tall: see height) */
  width: Record<string, number>;
  lqip: string;
}

export interface MotifEntry {
  motif: string;
  aspect: number;
  axis: 'width' | 'height';
  webp: Record<string, string>;
  mask?: boolean;
}

interface SpritesManifest {
  couples: Record<EventKey, CoupleEntry>;
  motifs: Record<string, MotifEntry>;
  textures: Record<string, { file: string; width: number; height: number }>;
  dabs: Record<string, { file: string; n: number; cell: number }>;
  bamboo: Record<string, { file: string; width: number; height: number }>;
}

export const SPRITES = manifest as unknown as SpritesManifest;

const FILES = import.meta.glob('../assets/sprites/**/*.{avif,webp}', {
  eager: true,
  query: '?url',
  import: 'default',
}) as Record<string, string>;

/** The hashed URL of a manifest path (`sprites/couple/mehndi-720h.avif`); '' when unknown. */
export function spriteUrl(rel: string): string {
  return FILES[`../assets/${rel}`] ?? '';
}

export function coupleEntry(event: string): CoupleEntry | undefined {
  return Object.prototype.hasOwnProperty.call(SPRITES.couples, event) ? SPRITES.couples[event as EventKey] : undefined;
}

/** The real pixel height of a couple file (the manifest key is nominal: Haldi's 960 is 927 px). */
export function coupleFileHeight(c: CoupleEntry, key: string): number {
  return Math.round((c.width[key] ?? 0) / c.aspect);
}

const round = (n: number, d = 0) => {
  const k = 10 ** d;
  return Math.round(n * k) / k;
};

/**
 * `sizes` entries for an element whose CSS height is `clamp(min, vh, max)` under `media` and whose width is
 * `factor` x its height. Viewport units are written as `vh` (sizes support is broad; svh <= vh only overestimates).
 */
export function clampToSizes(media: string, h: HeightClamp, factor: number): string[] {
  const and = (q: string) => (media ? `${media} and ${q}` : q);
  const out: string[] = [];
  if (h.min > 0) out.push(`${and(`(max-height: ${Math.floor(h.min / h.vh)}px)`)} ${Math.round(h.min * factor)}px`);
  out.push(`${and(`(max-height: ${Math.floor(h.max / h.vh)}px)`)} ${round(h.vh * 100 * factor, 2)}vh`);
  out.push(`${media ? `${media} ` : ''}${Math.round(h.max * factor)}px`);
  return out;
}

/** `sizes` for a couple: its drawn width in every layout of 5.2 (COUPLE_HEIGHT order = evaluation order). */
export function coupleSizes(c: Pick<CoupleEntry, 'aspect' | 'heightScale'>): string {
  const factor = c.aspect * c.heightScale;
  const parts: string[] = [];
  for (const row of COUPLE_HEIGHT) parts.push(...clampToSizes(row.media, row.h, factor));
  // the last entry has no media condition; anything after it would be ignored
  return parts.join(', ');
}

function coupleSrcSet(c: CoupleEntry, files: Record<string, string>): string {
  return Object.keys(files)
    .sort((a, b) => Number(a) - Number(b))
    .map((k) => `${spriteUrl(files[k] ?? '')} ${c.width[k] ?? k}w`)
    .join(', ');
}

export interface CoupleImage {
  sources: PictureSource[];
  img: { src: string; width: number; height: number; sizes: string; srcSet: string };
  lqip: string;
  /** CSS variables for the figure (layout.css `.couple`) */
  vars: Record<string, string>;
}

/** Everything a `<picture>` of an event couple needs, or undefined for an unknown event. */
export function coupleImage(event: string): CoupleImage | undefined {
  const c = coupleEntry(event);
  if (!c) return undefined;
  const sizes = coupleSizes(c);
  const keys = Object.keys(c.webp).sort((a, b) => Number(a) - Number(b));
  const big = keys[keys.length - 1] ?? '';
  const mid = keys[Math.min(1, keys.length - 1)] ?? big;
  return {
    sources: [{ type: 'image/avif', srcSet: coupleSrcSet(c, c.avif), sizes }],
    img: {
      src: spriteUrl(c.webp[mid] ?? ''),
      srcSet: coupleSrcSet(c, c.webp),
      sizes,
      width: c.width[big] ?? 0,
      height: coupleFileHeight(c, big),
    },
    lqip: c.lqip,
    vars: {
      '--couple-aspect': String(c.aspect),
      '--couple-hs': String(c.heightScale),
      '--couple-feet': String(c.figure.feet),
      '--couple-crown': String(c.figure.crown),
    },
  };
}

/** The largest CSS height a couple is ever drawn at (5.2 cap). */
export const COUPLE_CAP = COUPLE_MAX_PX;

/**
 * A painted motif sprite as `srcset` with width descriptors (height-keyed files are converted with the aspect),
 * plus the intrinsic size of the largest file for `width`/`height` attributes.
 */
export function motifSprite(
  id: string,
): { src: string; srcSet: string; width: number; height: number; mask: boolean } | undefined {
  const m = Object.prototype.hasOwnProperty.call(SPRITES.motifs, id) ? SPRITES.motifs[id] : undefined;
  if (!m) return undefined;
  const entries = Object.keys(m.webp)
    .map((k) => {
      const n = Number(k);
      const w = m.axis === 'width' ? n : Math.round(n * m.aspect);
      return { w, h: m.axis === 'width' ? Math.round(n / m.aspect) : n, url: spriteUrl(m.webp[k] ?? '') };
    })
    .sort((a, b) => a.w - b.w);
  const big = entries[entries.length - 1];
  if (!big) return undefined;
  return {
    src: big.url,
    srcSet: entries.map((e) => `${e.url} ${e.w}w`).join(', '),
    width: big.w,
    height: big.h,
    mask: Boolean(m.mask),
  };
}
